{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Cefuroxime axetil, a cephalosporin ester prodrug closely analogous to the query, had a mean absolute oral bioavailability of 64% (90% CI 58–69%) after a 500 mg oral dose, directly supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Amoxicillin, an aminopenicillin beta-lactam, showed an absolute oral bioavailability of 93% at 500 mg versus IV, supporting high oral absorption for beta-lactam antibiotics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ampicillin, a closely related beta-lactam, had an oral bioavailability of 62 ± 17% versus IV in healthy fasting subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Perindopril, an ester prodrug, had an absolute oral bioavailability of about 75%, supporting the high bioavailability expected for an ester prodrug strategy.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Faropenem, an oral beta-lactam, showed bioavailability of 72–84% in children, providing additional support for high oral bioavailability in this antibiotic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Loracarbef, a beta-lactam antibiotic, was approximately 90% bioavailable after oral administration, consistent with high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "PF-05241328 had an absolute oral bioavailability of 38% in humans, still clearly above the 20% threshold and supportive of a high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a beta-lactam ester prodrug. Multiple highly transferable experimental records from beta-lactam antibiotics and ester prodrugs report absolute oral bioavailability values mostly between 38% and 95%, all above the 20% threshold. The closest analogue, cefuroxime axetil, shows 64% absolute bioavailability. No affirmative threshold-relevant evidence supports low bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "The query's exact structural assignment is unusual; reliance on close beta-lactam and ester-prodrug analogues is necessary.",
    "Population variability and food effects are not fully captured by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

